select t.model_name,t.model_name modelName,t.model_adapt,t.model_adapt modelAdapt,t.model_id,t.model_id
modelId,t.status_cd,t.status_cd statusCd
from monitor_model t
where 1 =1

    and t.model_name like concat('%', #{modelName}, '%')


    and t.model_adapt like concat('%', #{modelAdapt}, '%')


    and t.model_id= #{modelId}


    and t.status_cd= #{statusCd}

order by t.create_time desc

    limit #{page}, #{row}

